const assert=require('node:assert/strict');
const vm=require('node:vm');
const fs=require('node:fs');
const src=fs.readFileSync('frontend/assets/blueplate-synthetic-demo.js','utf8');
const sandbox={window:{},Date,Math};vm.createContext(sandbox);vm.runInContext(src,sandbox);
const S=sandbox.window.BluePlateSynthetic;
assert.ok(S);
const a=S.metrics({restaurant_key:3,restaurant_name:'Test',zone_name:'UST - España Blvd'});
const b=S.metrics({restaurant_key:3,restaurant_name:'Test',zone_name:'UST - España Blvd'});
assert.equal(a.blended_rating,b.blended_rating);
assert.ok(a.blended_rating>=3.35&&a.blended_rating<=4.85);
assert.ok(a.proxy_delivery_mins>=19&&a.proxy_delivery_mins<45);
assert.ok(a.cancellation_risk_index>=2&&a.cancellation_risk_index<19);
assert.ok(['NORMAL','WARNING','CRITICAL'].includes(a.overall_health_status));
assert.equal(a.synthetic_demo,true);
assert.match(a.data_origin,/SYNTHETIC/);
assert.equal(S.trend({from:'2026-11-01',to:'2026-11-07'}).length,7);
assert.equal(S.trend({from:'2026-01-01',to:'2026-11-07'}).length,90);
assert.equal(S.trend({from:'2026-11-07',to:'2026-11-01'}).length,0);
const alerts=S.alerts([a],{to:'2026-11-15'});
assert.ok(Array.isArray(alerts));
assert.ok(S.reports([{id:3,name:'Test',zone:'Zone'}])[0].submission_source.includes('SYNTHETIC'));
console.log('Synthetic demo: 12 assertions/checks passed');
